CREATE TABLE IF NOT EXISTS specs ( id TEXT PRIMARY KEY, title TEXT NOT NULL, product_type TEXT, product_family TEXT, status TEXT NOT NULL DEFAULT 'draft', requested_by TEXT, data TEXT NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_specs_updated ON specs(updated_at DESC);
CREATE TABLE IF NOT EXISTS spec_values ( spec_id TEXT NOT NULL REFERENCES specs(id) ON DELETE CASCADE, section TEXT NOT NULL, key TEXT NOT NULL, value TEXT, num_value REAL );
CREATE INDEX IF NOT EXISTS idx_spec_values_key ON spec_values(key, value);
CREATE INDEX IF NOT EXISTS idx_spec_values_spec ON spec_values(spec_id);
CREATE TABLE IF NOT EXISTS spec_history ( spec_id TEXT NOT NULL, data TEXT NOT NULL, status TEXT, saved_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_spec_history_spec ON spec_history(spec_id, saved_at DESC);
CREATE TABLE IF NOT EXISTS product_families ( id TEXT PRIMARY KEY, name TEXT NOT NULL, notes TEXT, sort_order INTEGER DEFAULT 100, active INTEGER NOT NULL DEFAULT 1 );
INSERT OR IGNORE INTO product_families (id, name, notes, sort_order) VALUES ('omnistat', 'OmniStat', 'Placeholder — confirm enclosure / plastics details', 10), ('mystat', 'MyStat', 'Placeholder', 20), ('verosense', 'VeroSense', 'Placeholder', 30), ('smartnode', 'Smart Node', 'Placeholder', 40), ('ccu', 'CCU', 'Placeholder', 50), ('connect', 'Connect Module', 'Placeholder', 60);
CREATE TABLE IF NOT EXISTS products ( id TEXT PRIMARY KEY, name TEXT NOT NULL, family_id TEXT REFERENCES product_families(id), status TEXT DEFAULT 'active', notes TEXT );
CREATE TABLE IF NOT EXISTS product_capabilities ( product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, key TEXT NOT NULL, value TEXT, num_value REAL );
CREATE INDEX IF NOT EXISTS idx_product_caps_key ON product_capabilities(key, value);
CREATE TABLE IF NOT EXISTS boq_items ( part_no TEXT PRIMARY KEY, description TEXT NOT NULL, category TEXT, unit_cost REAL, currency TEXT DEFAULT 'USD', supplier TEXT, updated_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS boq_feature_map ( key TEXT NOT NULL, value TEXT, part_no TEXT NOT NULL REFERENCES boq_items(part_no), qty_rule TEXT DEFAULT '1' );
